    fun isAseresYemeiTeshuva(): Boolean = handle.borrow { _self ->
        JniBridge.kosher_calendar_HebrewDate_is_aseres_yemei_teshuva(_self)
    }

    /** The weekly portion read on this day, when it is a Shabbos with one. */
    fun parsha(region: Region): Parsha? = handle.borrow { _self ->
        decodeBuffer(JniBridge.kosher_calendar_HebrewDate_parsha(_self, region.value)) { _r -> unpackOptionalOfParsha(_r) }
    }

    /** The special Shabbos this is, such as Shabbos Zachor, if any. */
    fun specialParsha(region: Region): Parsha? = handle.borrow { _self ->
        decodeBuffer(JniBridge.kosher_calendar_HebrewDate_special_parsha(_self, region.value)) { _r -> unpackOptionalOfParsha(_r) }
    }

    /** The weekly portion of the coming Shabbos. */
    fun nextParsha(region: Region): Parsha? = handle.borrow { _self ->
        decodeBuffer(JniBridge.kosher_calendar_HebrewDate_next_parsha(_self, region.value)) { _r -> unpackOptionalOfParsha(_r) }
    }

    /** The molad of this month, in Unix milliseconds. */
    fun molad(): Long? = handle.borrow { _self ->
        decodeBuffer(JniBridge.kosher_calendar_HebrewDate_molad(_self)) { _r -> unpackOptionalOfI64(_r) }
    }

    /** The date as text, for example "15 Nisan 5784". */
    fun display(): String = handle.borrow { _self ->
        decodeUtf8(JniBridge.kosher_calendar_HebrewDate_display(_self))
    }

    /** Whether `other` is the same day. */
    fun equals_(other: HebrewDate): Boolean = handle.borrow { _self ->
        other.handle.borrow { _h0 ->
            JniBridge.kosher_calendar_HebrewDate_equals(_self, _h0)
        }
    }

    /** -1, 0 or 1 as this date is before, the same as, or after `other`. */
    fun compare(other: HebrewDate): Int = handle.borrow { _self ->
        other.handle.borrow { _h0 ->
            JniBridge.kosher_calendar_HebrewDate_compare(_self, _h0)
        }
    }

    /** Releases this wrapper's native reference; safe to call more than once. */
    override fun close() = handle.close()

    companion object {
        /** Adopts one strong reference (a return value or a buffer token). */
        internal fun fromHandle(address: Long): HebrewDate = HebrewDate(address)

        /** [fromHandle], with address 0 meaning no object. */
        internal fun fromHandleOrNull(address: Long): HebrewDate? = if (address == 0L) null else HebrewDate(address)

        /**
         * The date `day` `month` `year`, for example 15 Nisan 5785.
         *
         * # Errors
         *
         * `KosherError::InvalidDate` when there is no such day: day 0, day 30 of a 29-day
         * month, Adar I in a common year, or a year outside the supported range.
         */
        operator fun invoke(year: Int, month: HebrewMonth, day: Int): HebrewDate = HebrewDate.fromHandle(JniBridge.kosher_calendar_HebrewDate_new(year, month.value, day))

        /**
         * The Hebrew date of a Gregorian date.
         *
         * # Errors
         *
         * `KosherError::InvalidDate` when `date` does not exist.
         */
        fun fromGregorian(date: GregorianDate): HebrewDate = HebrewDate.fromHandle(JniBridge.kosher_calendar_HebrewDate_from_gregorian(encodeBuffer { _w -> packGregorianDate(_w, date) }))
    }
}

