            ?: throw NativeBugException(-3, "unknown Category value $value")
    }
}

/** The solar position algorithm. */
enum class Calculator(val value: Int) {
    /** The NOAA algorithm, KosherJava's default. Good to about a minute. */
    Noaa(0),
    /** Jean Meeus's higher-accuracy VSOP87 algorithm. */
    Meeus(1),
    /** The NREL Solar Position Algorithm, solved on the topocentric zenith. */
    Spa(2);

    companion object {
        /** The variant whose ABI value is [value]. */
        fun fromValue(value: Int): Calculator = entries.firstOrNull { it.value == value }
            ?: throw NativeBugException(-3, "unknown Calculator value $value")
    }
}

/** Why a time in `ZmanTime` could not be calculated. */
enum class ZmanFailure(val value: Int) {
    /** The sun stays above the angle the time needs all day. */
    AllDay(0),
    /** The sun stays below the angle the time needs all day. */
    AllNight(1),
    /** The time does not apply on this date. */
    NotApplicable(2),
    /** The time needs a time zone and none was given. */
    TimeZoneRequired(3),
    /** The time zone callback failed. */
    TimeZoneCallbackFailed(4),
    /** An internal calculation error. */
    Internal(5);

    companion object {
        /** The variant whose ABI value is [value]. */
        fun fromValue(value: Int): ZmanFailure = entries.firstOrNull { it.value == value }
            ?: throw NativeBugException(-3, "unknown ZmanFailure value $value")
    }
}

/** How `Zmanim` calculates. `default_config` matches KosherJava's defaults. */
data class Config(
    /**
     * How long before sea-level sunset candle lighting is, in minutes, at most 1440 either
     * way. Default 18.
     */
    val candle_lighting_minutes: Int,
    /** Whether proportional zmanim divide the day at astronomical *chatzos*. Default false. */
    val use_astronomical_chatzos_for_other_zmanim: Boolean,
    /**
     * Whether elevation adjusts every zman built on sunrise and sunset, not only sunrise
     * and sunset themselves. Default false.
     */
    val use_elevation: Boolean,
    /**
     * How long after sunset Tzais Ateret Torah is, in minutes, at most 1440 either way.
     * Default 40.
     */
    val ateret_torah_sunset_minutes: Int,
    /**
     * Whether *chatzos* is the sun's transit rather than the midpoint of sunrise and
     * sunset. Default true.
     */
    val use_astronomical_chatzos: Boolean,
    /** The solar position algorithm. Default NOAA. */
    val calculator: Calculator,
    /** For Meeus and SPA: whether to apply the delta-T (TT - UT) correction. Default true. */
    val apply_delta_t: Boolean,
)

internal fun packConfig(_w: BufferWriter, _v: Config) {
    _w.writeI32(_v.candle_lighting_minutes)
    _w.writeBool(_v.use_astronomical_chatzos_for_other_zmanim)
    _w.writeBool(_v.use_elevation)
    _w.writeI32(_v.ateret_torah_sunset_minutes)
    _w.writeBool(_v.use_astronomical_chatzos)
    _w.writeI32(_v.calculator.value)
    _w.writeBool(_v.apply_delta_t)
}

internal fun unpackConfig(_r: BufferReader): Config = Config(
    _r.readI32(),
    _r.readBool(),
    _r.readBool(),
    _r.readI32(),
    _r.readBool(),
    Calculator.fromValue(_r.readI32()),
    _r.readBool(),
)

/** One zman's time, or why it has none. */
data class ZmanTime(
    /** The zman. */
    val zman: Zman,
    /** The time in Unix milliseconds, when it could be calculated. */
    val time: Long?,
    /** Why it could not, when it could not. */
    val failure: ZmanFailure?,
)

internal fun packZmanTime(_w: BufferWriter, _v: ZmanTime) {
    _w.writeI32(_v.zman.value)
    packOptionalOfI64(_w, _v.time)
    packOptionalOfZmanFailure(_w, _v.failure)
}

internal fun unpackZmanTime(_r: BufferReader): ZmanTime = ZmanTime(
    Zman.fromValue(_r.readI32()),
    unpackOptionalOfI64(_r),
    unpackOptionalOfZmanFailure(_r),
)

/**
 * The time zone, supplied by the caller: the offset from UTC at an instant.
 *
 * Only the Kiddush Levana times, and places more than 150 degrees from Greenwich, need
 * one. It is called synchronously, once for each sunrise, sunset or other event a time is
 * built from.
 */
interface TimeZoneOffset {
    /**
     * The offset from UTC, in seconds east, in effect at `unix_seconds`.
     *
     * # Errors
     *
     * Fail when the offset is unknown; the calculation then reports
     * `KosherError::TimeZoneCallbackFailed`.
     */
    fun offsetSeconds(unixSeconds: Long): Int
}

/** The *zmanim* for one place on one day. */
class Zmanim private constructor(address: Long) : AutoCloseable {
    internal val handle: NativeHandle = NativeCleaner.register(this, NativeHandle(address, JniBridge::kosher_zmanim_Zmanim_destroy))

    /** A new strong reference to this object, as written into a value buffer. */
    internal fun cloneHandle(): Long = handle.borrow { JniBridge.kosher_zmanim_Zmanim_clone(it) }

    /**
     * The time of `zman`, in Unix milliseconds.
     *
     * # Errors
     *
     * `KosherError::AllDay` or `KosherError::AllNight` where the sun never reaches
     * the angle the time needs; `KosherError::NotApplicable` for a time that only exists
     * on some days; `KosherError::TimeZoneRequired` for the Kiddush Levana times without
     * a time zone; `KosherError::TimeZoneCallbackFailed` when the callback failed.
     */
    fun get(zman: Zman): Long = handle.borrow { _self ->
        JniBridge.kosher_zmanim_Zmanim_get(_self, zman.value)
    }

    /** Every zman, with its time or why it has none. */
    fun all(): List<ZmanTime> = handle.borrow { _self ->
        decodeBuffer(JniBridge.kosher_zmanim_Zmanim_all(_self)) { _r -> unpackListOfZmanTime(_r) }
    }

    /**
     * When the sun is `degrees` below the geometric horizon before sunrise, in Unix
     * milliseconds.
     *
     * # Errors
     *
     * The same as `get`.
     */
    fun sunriseOffsetByDegrees(degrees: Double): Long = handle.borrow { _self ->
        JniBridge.kosher_zmanim_Zmanim_sunrise_offset_by_degrees(_self, degrees)
    }

    /**
     * When the sun is `degrees` below the geometric horizon after sunset, in Unix
     * milliseconds.
     *
     * # Errors
     *
     * The same as `get`.
     */
    fun sunsetOffsetByDegrees(degrees: Double): Long = handle.borrow { _self ->
        JniBridge.kosher_zmanim_Zmanim_sunset_offset_by_degrees(_self, degrees)
    }

    /** The location. */
    fun location(): Location = handle.borrow { _self ->
        decodeBuffer(JniBridge.kosher_zmanim_Zmanim_location(_self)) { _r -> unpackLocation(_r) }
    }

    /** The date. */
    fun date(): GregorianDate = handle.borrow { _self ->
        decodeBuffer(JniBridge.kosher_zmanim_Zmanim_date(_self)) { _r -> unpackGregorianDate(_r) }
    }

    /** The configuration. */
    fun config(): Config = handle.borrow { _self ->
        decodeBuffer(JniBridge.kosher_zmanim_Zmanim_config(_self)) { _r -> unpackConfig(_r) }
    }

    /** Releases this wrapper's native reference; safe to call more than once. */
    override fun close() = handle.close()

    companion object {
        /** Adopts one strong reference (a return value or a buffer token). */
        internal fun fromHandle(address: Long): Zmanim = Zmanim(address)

        /** [fromHandle], with address 0 meaning no object. */
        internal fun fromHandleOrNull(address: Long): Zmanim? = if (address == 0L) null else Zmanim(address)

        /**
         * The *zmanim* at `location` on `date`, calculated with `config`, in `time_zone`.
         *
         * # Errors
         *
         * `KosherError::InvalidDate` for a date that does not exist;
         * `KosherError::InvalidMinutes` for a candle-lighting or Ateret Torah offset of more
         * than a day; the errors of `validate_location`.
         */
        operator fun invoke(location: Location, date: GregorianDate, config: Config, timeZone: TimeZoneOffset?): Zmanim = Zmanim.fromHandle(JniBridge.kosher_zmanim_Zmanim_new(encodeBuffer { _w -> packLocation(_w, location) }, encodeBuffer { _w -> packGregorianDate(_w, date) }, encodeBuffer { _w -> packConfig(_w, config) }, timeZone))
    }
}

