/** A day's portion of Tehillim. */
sealed class TehillimUnit {
    /** Whole chapters, `start` to `end` inclusive. */
    data class Psalms(
        /** The first chapter. */
        val start: Int,
        /** The last chapter. */
        val end: Int,
    ) : TehillimUnit()
    /** Part of one long chapter (119, split over two days). */
    data class PsalmVerses(
        /** The chapter. */
        val psalm: Int,
        /** The first verse. */
        val start_verse: Int,
        /** The last verse. */
        val end_verse: Int,
    ) : TehillimUnit()
}

internal fun packTehillimUnit(_w: BufferWriter, _v: TehillimUnit) {
    when (_v) {
        is TehillimUnit.Psalms -> {
            _w.writeI32(0)
            _w.writeI32(_v.start)
            _w.writeI32(_v.end)
        }
        is TehillimUnit.PsalmVerses -> {
            _w.writeI32(1)
            _w.writeI32(_v.psalm)
            _w.writeI32(_v.start_verse)
            _w.writeI32(_v.end_verse)
        }
    }
}

internal fun unpackTehillimUnit(_r: BufferReader): TehillimUnit = when (val _tag = _r.readI32()) {
    0 -> TehillimUnit.Psalms(_r.readI32(), _r.readI32())
    1 -> TehillimUnit.PsalmVerses(_r.readI32(), _r.readI32(), _r.readI32())
    else -> throw NativeBugException(-3, "malformed value buffer: unknown TehillimUnit tag $_tag")
}

/** The Pirkei Avos read on a Shabbos afternoon. */
sealed class PirkeiAvosUnit {
    /** One chapter. */
    data class Single(
        /** The chapter, 1 to 6. */
        val chapter: Int,
    ) : PirkeiAvosUnit()
    /** Two chapters read together, at the end of the summer. */
    data class Combined(
        /** The first chapter. */
        val first: Int,
        /** The second chapter. */
        val second: Int,
    ) : PirkeiAvosUnit()
}

internal fun packPirkeiAvosUnit(_w: BufferWriter, _v: PirkeiAvosUnit) {
    when (_v) {
        is PirkeiAvosUnit.Single -> {
            _w.writeI32(0)
            _w.writeI32(_v.chapter)
        }
        is PirkeiAvosUnit.Combined -> {
            _w.writeI32(1)
            _w.writeI32(_v.first)
            _w.writeI32(_v.second)
        }
    }
}

internal fun unpackPirkeiAvosUnit(_r: BufferReader): PirkeiAvosUnit = when (val _tag = _r.readI32()) {
    0 -> PirkeiAvosUnit.Single(_r.readI32())
    1 -> PirkeiAvosUnit.Combined(_r.readI32(), _r.readI32())
    else -> throw NativeBugException(-3, "malformed value buffer: unknown PirkeiAvosUnit tag $_tag")
}

/** A page (*daf*) of the Talmud: both sides of one leaf. */
data class Daf(
    /** The tractate. */
    val tractate: Tractate,
    /** The page number. The Bavli starts at 2, the Yerushalmi at 1. */
    val daf: Int,
    /** As text, for example "Bava Metzia 55". */
    val display: String,
)

internal fun packDaf(_w: BufferWriter, _v: Daf) {
    _w.writeI32(_v.tractate.value)
    _w.writeI32(_v.daf)
    _w.writeString(_v.display)
}

internal fun unpackDaf(_r: BufferReader): Daf = Daf(
    Tractate.fromValue(_r.readI32()),
    _r.readI32(),
    _r.readString(),
)

/** One side of a page (*amud*). */
data class Amud(
    /** The tractate. */
    val tractate: Tractate,
    /** The page number. */
    val daf: Int,
    /** Which side of the page. */
    val side: Side,
    /** As text, for example "Bava Metzia 55b". */
    val display: String,
)

internal fun packAmud(_w: BufferWriter, _v: Amud) {
    _w.writeI32(_v.tractate.value)
    _w.writeI32(_v.daf)
    _w.writeI32(_v.side.value)
    _w.writeString(_v.display)
}

internal fun unpackAmud(_r: BufferReader): Amud = Amud(
    Tractate.fromValue(_r.readI32()),
    _r.readI32(),
    Side.fromValue(_r.readI32()),
    _r.readString(),
)

/** One *mishnah*. */
data class Mishna(
    /** The tractate. */
    val tractate: Tractate,
    /** The chapter (*perek*), from 1. */
    val chapter: Int,
    /** The *mishnah* within the chapter, from 1. */
    val mishna: Int,
    /** As text, for example "Nazir 5:5". */
    val display: String,
)

internal fun packMishna(_w: BufferWriter, _v: Mishna) {
    _w.writeI32(_v.tractate.value)
    _w.writeI32(_v.chapter)
    _w.writeI32(_v.mishna)
    _w.writeString(_v.display)
}

internal fun unpackMishna(_r: BufferReader): Mishna = Mishna(
    Tractate.fromValue(_r.readI32()),
    _r.readI32(),
    _r.readI32(),
    _r.readString(),
)

/** The two *mishnayos* of a day of Mishna Yomis. */
data class MishnaPair(
    /** The first *mishnah*. */
    val first: Mishna,
    /** The second, the next *mishnah* in order. */
    val second: Mishna,
    /** As text, for example "Nazir 5:5-6". */
    val display: String,
)

internal fun packMishnaPair(_w: BufferWriter, _v: MishnaPair) {
    packMishna(_w, _v.first)
    packMishna(_w, _v.second)
    _w.writeString(_v.display)
}

internal fun unpackMishnaPair(_r: BufferReader): MishnaPair = MishnaPair(
    unpackMishna(_r),
    unpackMishna(_r),
    _r.readString(),
)

/** One row of the MyZmanim website's "All zmanim" table, in the table's order. */
enum class MyZman(val value: Int) {
    /** Dawn, 90 minutes as degrees. */
    Dawn90Degrees(0),
    /** Dawn, fixed 72 minutes. */
    Dawn72Fixed(1),
    /** Dawn, 72 minutes as 16.1 degrees. */
    Dawn72Degrees(2),
    /** Earliest talis & tefillin, 11.5 degrees. */
    Talis11Point5Degrees(3),
    /** Earliest talis & tefillin, 11 degrees. */
    Talis11Degrees(4),
    /** Earliest talis & tefillin, 10.2 degrees. */
    Talis10Point2Degrees(5),
    /** Sunrise, level region. */
    SunriseLevel(6),
    /** Sunrise, elevated observer/horizon. */
    SunriseElevated(7),
    /** Latest shema Magen Avraham, 90 minutes as degrees. */
    ShemaMA90Degrees(8),
    /** Latest shema Magen Avraham, fixed 72 minutes. */
    ShemaMA72Fixed(9),
    /** Latest shema Magen Avraham, 72 minutes as 16.1 degrees. */
    ShemaMA72Degrees(10),
    /** Latest shema Gra & Baal HaTanya. */
    ShemaGra(11),
    /** Latest shacharis Magen Avraham, 90 minutes as degrees. */
    ShacharisMA90Degrees(12),
    /** Latest shacharis Magen Avraham, fixed 72 minutes. */
    ShacharisMA72Fixed(13),
    /** Latest shacharis Magen Avraham, 72 minutes as 16.1 degrees. */
    ShacharisMA72Degrees(14),
    /** Latest shacharis Gra & Baal HaTanya. */
    ShacharisGra(15),
    /** Midday. */
    Midday(16),
    /** Earliest mincha, 30 fixed minutes after midday. */
    Mincha30Fixed(17),
    /** Earliest mincha, Gra & Baal HaTanya. */
    MinchaGra(18),
    /** Earliest mincha, lechumra. */
    MinchaLechumra(19),
    /** Earliest mincha, Magen Avraham fixed 72 minutes. */
    MinchaMA72Fixed(20),
    /** Mincha ketana, Gra & Baal HaTanya. */
    KetanaGra(21),
    /** Mincha ketana, Magen Avraham fixed 72 minutes. */
    KetanaMA72Fixed(22),
    /** Plag hamincha, Gra & Baal HaTanya. */
    PlagGra(23),
    /** Plag hamincha, Magen Avraham fixed 72 minutes. */
    PlagMA72Fixed(24),
    /** Candle lighting. */
    CandleLighting(25),
    /** Sunset, level region. */
    SunsetLevel(26),
    /** Sunset, elevated observer/horizon. */
    SunsetElevated(27),
    /** Gra's nightfall, 13 1/2 minutes as degrees. */
    NightGra18Minutes(28),
    /** Gra's nightfall, 16 7/8 minutes as degrees. */
    NightGra22Point5Minutes(29),
    /** Gra's nightfall, 18 minutes as degrees. */
    NightGra24Minutes(30),
    /** Gra's nightfall, 24 minutes as degrees, R' Schneur Zalman. */
    NightZalman(31),
    /** End of ordained fasts, R' Tukaccinsky. */
    NightFastTukaccinsky(32),
    /** End of ordained fasts, R' Moshe Feinstein. */
    NightFastFeinstein(33),
    /** 3 stars emerge, Sefer Moed Moadim. */
    NightMoed(34),
    /** 3 stars emerge, end of Shabbos and Yom Tov. */
    NightShabbos(35),
    /** 3 stars emerge, Chazon Ish. */
    NightChazonIsh(36),
    /** R' Tam's nightfall, fixed 72 minutes. */
    NightRTam72Fixed(37),
    /** R' Tam's nightfall, 72 minutes as 16.1 degrees. */
    NightRTam72Degrees(38),
    /** Midnight. */
    Midnight(39);

    companion object {
        /** The variant whose ABI value is [value]. */
        fun fromValue(value: Int): MyZman = entries.firstOrNull { it.value == value }
            ?: throw NativeBugException(-3, "unknown MyZman value $value")
    }
}

/** One MyZmanim time, or why it has none. */
data class MyZmanTime(
    /** The row. */
    val zman: MyZman,
    /** The time in Unix milliseconds, when it could be calculated. */
    val time: Long?,
    /** Why it could not, when it could not. */
    val failure: ZmanFailure?,
)

internal fun packMyZmanTime(_w: BufferWriter, _v: MyZmanTime) {
    _w.writeI32(_v.zman.value)
    packOptionalOfI64(_w, _v.time)
    packOptionalOfZmanFailure(_w, _v.failure)
}

internal fun unpackMyZmanTime(_r: BufferReader): MyZmanTime = MyZmanTime(
    MyZman.fromValue(_r.readI32()),
    unpackOptionalOfI64(_r),
    unpackOptionalOfZmanFailure(_r),
)

/**
 * MyZmanim's *zmanim* for one place on one day. The location's elevation and horizons
 * matter: MyZmanim gives both "level" and "elevated" sunrise and sunset.
 */
class MyZmanim private constructor(address: Long) : AutoCloseable {
    internal val handle: NativeHandle = NativeCleaner.register(this, NativeHandle(address, JniBridge::kosher_myzmanim_MyZmanim_destroy))

    /** A new strong reference to this object, as written into a value buffer. */
    internal fun cloneHandle(): Long = handle.borrow { JniBridge.kosher_myzmanim_MyZmanim_clone(it) }

    /**
     * The time of `zman`, in Unix milliseconds.
     *
     * # Errors
     *
     * `KosherError::AllDay` or `KosherError::AllNight` where the website shows no
     * time; `KosherError::TimeZoneCallbackFailed` when the callback failed.
     */
    fun get(zman: MyZman): Long = handle.borrow { _self ->
        JniBridge.kosher_myzmanim_MyZmanim_get(_self, zman.value)
    }

    /** Every row, with its time or why it has none. */
    fun all(): List<MyZmanTime> = handle.borrow { _self ->
        decodeBuffer(JniBridge.kosher_myzmanim_MyZmanim_all(_self)) { _r -> unpackListOfMyZmanTime(_r) }
    }

    /**
     * A twelfth of the day from sea-level sunrise to sea-level sunset, in milliseconds.
     *
     * # Errors
     *
     * The same as `get`.
     */
    fun proportionalHourGra(): Long = handle.borrow { _self ->
        JniBridge.kosher_myzmanim_MyZmanim_proportional_hour_gra(_self)
    }

    /** The location. */
    fun location(): Location = handle.borrow { _self ->
        decodeBuffer(JniBridge.kosher_myzmanim_MyZmanim_location(_self)) { _r -> unpackLocation(_r) }
    }

    /** The date. */
    fun date(): GregorianDate = handle.borrow { _self ->
        decodeBuffer(JniBridge.kosher_myzmanim_MyZmanim_date(_self)) { _r -> unpackGregorianDate(_r) }
    }

    /** The minutes before sunset of candle lighting. */
    fun candleLightingMinutes(): Double = handle.borrow { _self ->
        JniBridge.kosher_myzmanim_MyZmanim_candle_lighting_minutes(_self)
    }

    /** Releases this wrapper's native reference; safe to call more than once. */
    override fun close() = handle.close()

    companion object {
        /** Adopts one strong reference (a return value or a buffer token). */
        internal fun fromHandle(address: Long): MyZmanim = MyZmanim(address)

        /** [fromHandle], with address 0 meaning no object. */
        internal fun fromHandleOrNull(address: Long): MyZmanim? = if (address == 0L) null else MyZmanim(address)

        /**
         * The *zmanim* at `location` on `date`, lighting candles `candle_lighting_minutes`
         * before sunset (the site's default is 18).
         *
         * # Errors
         *
         * `KosherError::InvalidDate` for a date that does not exist;
         * `KosherError::InvalidMinutes` when `candle_lighting_minutes` is not a finite number
         * of at most 1440 either way; the errors of `validate_location`.
         */
        operator fun invoke(location: Location, date: GregorianDate, candleLightingMinutes: Double, timeZone: TimeZoneOffset?): MyZmanim = MyZmanim.fromHandle(JniBridge.kosher_myzmanim_MyZmanim_new(encodeBuffer { _w -> packLocation(_w, location) }, encodeBuffer { _w -> packGregorianDate(_w, date) }, candleLightingMinutes, timeZone))
    }
}

/**
 * Jewish calendar, halachic times (*zmanim*) and daily learning schedules.
 *
 * Instants are milliseconds since the Unix epoch and durations are milliseconds.
 */
object Kosher {
    /** A location at sea level, with flat horizons. */
    fun seaLevelLocation(latitude: Double, longitude: Double): Location = decodeBuffer(JniBridge.kosher_sea_level_location(latitude, longitude)) { _r -> unpackLocation(_r) }

    /**
     * Checks a location the way `Zmanim` will.
     *
     * # Errors
     *
     * `KosherError::InvalidLatitude`, `KosherError::InvalidLongitude` or
     * `KosherError::InvalidElevation`; `KosherError::TimeZoneRequired` beyond 150 degrees
     * from Greenwich when `has_time_zone` is false.
     */
    fun validateLocation(location: Location, hasTimeZone: Boolean) {
        JniBridge.kosher_validate_location(encodeBuffer { _w -> packLocation(_w, location) }, hasTimeZone)
    }

    /** The Hebrew calendar: dates, holidays, the weekly *parsha*, years and the molad. */
    object Calendar {
        /** Facts about the Hebrew year `year`. */
        fun yearInfo(year: Int): YearInfo = decodeBuffer(JniBridge.kosher_calendar_year_info(year)) { _r -> unpackYearInfo(_r) }

        /** The number of days in `month` of `year`, or none when the year has no such month. */
        fun daysInMonth(year: Int, month: HebrewMonth): Int? = decodeBuffer(JniBridge.kosher_calendar_days_in_month(year, month.value)) { _r -> unpackOptionalOfI32(_r) }

        /**
         * 1 Tishrei of `year`.
         *
         * # Errors
         *
         * `KosherError::InvalidDate` for a year outside the supported range.
         */
        fun roshHashana(year: Int): HebrewDate = HebrewDate.fromHandle(JniBridge.kosher_calendar_rosh_hashana(year))

        /** The holiday's English name, for example "Chanukah". */
        fun holidayName(holiday: Holiday): String = decodeUtf8(JniBridge.kosher_calendar_holiday_name(encodeBuffer { _w -> packHoliday(_w, holiday) }))

        /** The holiday's Hebrew name. */
        fun holidayHebrew(holiday: Holiday): String = decodeUtf8(JniBridge.kosher_calendar_holiday_hebrew(encodeBuffer { _w -> packHoliday(_w, holiday) }))

        /** Whether melacha is forbidden on the holiday. */
        fun holidayIsAssurBemelacha(holiday: Holiday): Boolean = JniBridge.kosher_calendar_holiday_is_assur_bemelacha(encodeBuffer { _w -> packHoliday(_w, holiday) })

        /** Whether the holiday is a modern Israeli one, such as Yom Ha'atzmaut. */
        fun holidayIsModern(holiday: Holiday): Boolean = JniBridge.kosher_calendar_holiday_is_modern(encodeBuffer { _w -> packHoliday(_w, holiday) })

        /** Whether the holiday is a fast day. */
        fun holidayIsFastDay(holiday: Holiday): Boolean = JniBridge.kosher_calendar_holiday_is_fast_day(encodeBuffer { _w -> packHoliday(_w, holiday) })

        /** The portion's English name, for example "Lech Lecha". */
        fun parshaName(parsha: Parsha): String = decodeUtf8(JniBridge.kosher_calendar_parsha_name(parsha.value))

        /** The portion's Hebrew name. */
        fun parshaHebrew(parsha: Parsha): String = decodeUtf8(JniBridge.kosher_calendar_parsha_hebrew(parsha.value))

        /** The month's English name, for example "Nisan". */
        fun monthName(month: HebrewMonth): String = decodeUtf8(JniBridge.kosher_calendar_month_name(month.value))

        /** The month's Hebrew name. */
        fun monthHebrew(month: HebrewMonth): String = decodeUtf8(JniBridge.kosher_calendar_month_hebrew(month.value))
    }

    /** Halachic times (*zmanim*) for a place and a day. */
    object ZmanimModule {
        /** KosherJava's default configuration. */
        fun defaultConfig(): Config = decodeBuffer(JniBridge.kosher_zmanim_default_config()) { _r -> unpackConfig(_r) }

        /** Every zman, grouped by `Category`. */
        fun allZmanim(): List<Zman> = decodeBuffer(JniBridge.kosher_zmanim_all_zmanim()) { _r -> unpackListOfZman(_r) }

        /** The zman's display name, for example "Sof Zman Shma (GR'A)". */
        fun zmanName(zman: Zman): String = decodeUtf8(JniBridge.kosher_zmanim_zman_name(zman.value))

        /** The KosherJava method that calculates the zman, for example "getSofZmanShmaGRA". */
        fun zmanJavaName(zman: Zman): String = decodeUtf8(JniBridge.kosher_zmanim_zman_java_name(zman.value))

        /** The zman named by its KosherJava method, for example "getSofZmanShmaGRA". */
        fun zmanFromJavaName(javaName: String): Zman? = decodeBuffer(JniBridge.kosher_zmanim_zman_from_java_name(encodeUtf8(javaName))) { _r -> unpackOptionalOfZman(_r) }

        /** What kind of time the zman is. */
        fun zmanCategory(zman: Zman): Category = Category.fromValue(JniBridge.kosher_zmanim_zman_category(zman.value))

        /** Whether KosherJava deprecates the zman. */
        fun zmanIsDeprecated(zman: Zman): Boolean = JniBridge.kosher_zmanim_zman_is_deprecated(zman.value)

        /**
         * A paragraph or two explaining the zman to users, with the offsets from `config` filled
         * in. May contain Markdown links.
         */
        fun zmanDescription(zman: Zman, config: Config): String = decodeUtf8(JniBridge.kosher_zmanim_zman_description(zman.value, encodeBuffer { _w -> packConfig(_w, config) }))

        /** The algorithm's descriptive name, as KosherJava's `getCalculatorName` gives it. */
        fun calculatorName(calculator: Calculator): String = decodeUtf8(JniBridge.kosher_zmanim_calculator_name(calculator.value))

        /**
         * A *shaah zmanis*: a twelfth of the day from `start` to `end` (Unix milliseconds), in
         * milliseconds.
         */
        fun shaahZmanis(start: Long, end: Long): Long = JniBridge.kosher_zmanim_shaah_zmanis(start, end)
    }

    /**
     * Daily learning schedules: Daf Yomi, Mishna Yomis, Tehillim and the others.
     *
     * Each function gives the portion for a date, or none when nothing is scheduled (before the
     * program began, on Shabbos for a weekly program, outside the Pirkei Avos season).
     */
    object Limudim {
        /** The tractate's English name, for example "Bava Metzia". */
        fun tractateName(tractate: Tractate): String = decodeUtf8(JniBridge.kosher_limudim_tractate_name(tractate.value))

        /** The tractate's Hebrew name. */
        fun tractateHebrew(tractate: Tractate): String = decodeUtf8(JniBridge.kosher_limudim_tractate_hebrew(tractate.value))

        /** The portion as text, for example "Tehillim 1-9". */
        fun tehillimDisplay(unit: TehillimUnit): String = decodeUtf8(JniBridge.kosher_limudim_tehillim_display(encodeBuffer { _w -> packTehillimUnit(_w, unit) }))

        /** The portion as text, for example "Pirkei Avos 5-6". */
        fun pirkeiAvosDisplay(unit: PirkeiAvosUnit): String = decodeUtf8(JniBridge.kosher_limudim_pirkei_avos_display(encodeBuffer { _w -> packPirkeiAvosUnit(_w, unit) }))

        /** Daf Yomi: a page of the Babylonian Talmud a day, from 11 September 1923. */
        fun dafYomiBavli(date: HebrewDate): Daf? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.kosher_limudim_daf_yomi_bavli(_h0)) { _r -> unpackOptionalOfDaf(_r) }
        }

        /** Daf Hashavua: a page of the Babylonian Talmud a week. */
        fun dafHashavuaBavli(date: HebrewDate): Daf? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.kosher_limudim_daf_hashavua_bavli(_h0)) { _r -> unpackOptionalOfDaf(_r) }
        }

        /** Daf Yomi Yerushalmi: a page of the Jerusalem Talmud a day. */
        fun dafYomiYerushalmi(date: HebrewDate): Daf? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.kosher_limudim_daf_yomi_yerushalmi(_h0)) { _r -> unpackOptionalOfDaf(_r) }
        }

        /** Dirshu's Amud Yomi: one side of a page of the Babylonian Talmud a day. */
        fun amudYomiDirshu(date: HebrewDate): Amud? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.kosher_limudim_amud_yomi_dirshu(_h0)) { _r -> unpackOptionalOfAmud(_r) }
        }

        /** Mishna Yomis: two *mishnayos* a day, from 20 May 1947. */
        fun mishnaYomis(date: HebrewDate): MishnaPair? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.kosher_limudim_mishna_yomis(_h0)) { _r -> unpackOptionalOfMishnaPair(_r) }
        }

        /** Tehillim divided over the days of the Hebrew month. */
        fun tehillimMonthly(date: HebrewDate): TehillimUnit? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.kosher_limudim_tehillim_monthly(_h0)) { _r -> unpackOptionalOfTehillimUnit(_r) }
        }

        /** Pirkei Avos: a chapter each Shabbos afternoon from Pesach to Rosh Hashana. */
        fun pirkeiAvos(date: HebrewDate, region: Region): PirkeiAvosUnit? = date.handle.borrow { _h0 ->
            decodeBuffer(JniBridge.kosher_limudim_pirkei_avos(_h0, region.value)) { _r -> unpackOptionalOfPirkeiAvosUnit(_r) }
        }
    }

    /** The *zmanim* of the MyZmanim website, reproduced to the second. */
    object Myzmanim {
        /** The row's name as the website shows it. */
        fun myZmanName(zman: MyZman): String = decodeUtf8(JniBridge.kosher_myzmanim_my_zman_name(zman.value))

        /** Every row, in the website's order. */
        fun allMyZmanim(): List<MyZman> = decodeBuffer(JniBridge.kosher_myzmanim_all_my_zmanim()) { _r -> unpackListOfMyZman(_r) }

        /** The sun's depression for "90 minutes as degrees": 19.75 degrees. */
        fun dawn90Degrees(): Double = JniBridge.kosher_myzmanim_dawn_90_degrees()

        /** The sun's depression for "72 minutes as 16.1 degrees". */
        fun dawn72Degrees(): Double = JniBridge.kosher_myzmanim_dawn_72_degrees()

        /** Refraction at a sea-level horizon, in arcminutes. */
        fun seaLevelRefractionArcminutes(): Double = JniBridge.kosher_myzmanim_sea_level_refraction_arcminutes()

        /** The dip of the horizon per square root of a meter of height, in degrees. */
        fun dipDegreesPerRootMeter(): Double = JniBridge.kosher_myzmanim_dip_degrees_per_root_meter()

        /** The website's default minutes before sunset for candle lighting. */
        fun defaultCandleLightingMinutes(): Double = JniBridge.kosher_myzmanim_default_candle_lighting_minutes()
    }
}

